import{c as d,Q as a,j as r,m as e}from"./chunks/framework.BIK1AyNB.js";const u=JSON.parse('{"title":"🔧 技能系统","description":"","frontmatter":{},"headers":[],"relativePath":"skills/index.md","filePath":"skills/index.md","lastUpdated":1778824692000}'),i={name:"skills/index.md"};function l(h,t,n,o,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="🔧-技能系统" tabindex="-1">🔧 技能系统 <a class="header-anchor" href="#🔧-技能系统" aria-label="Permalink to &quot;🔧 技能系统&quot;">​</a></h1><p>B41 共有 <strong>24 个技能</strong>，分为 5 大类。每个技能有 0-10 级，升级获得经验。</p><h2 id="技能分类" tabindex="-1">技能分类 <a class="header-anchor" href="#技能分类" aria-label="Permalink to &quot;技能分类&quot;">​</a></h2><h3 id="制造类-crafting" tabindex="-1">制造类 (Crafting) <a class="header-anchor" href="#制造类-crafting" aria-label="Permalink to &quot;制造类 (Crafting)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>经验来源</th><th>Lv1 XP</th><th>关键解锁</th></tr></thead><tbody><tr><td>木工 (Carpentry)</td><td>锯木板、建造家具、拆家具</td><td>0/150</td><td>Lv4 雨水收集器, Lv7 楼梯</td></tr><tr><td>烹饪 (Cooking)</td><td>做饭、切食材</td><td>0/75</td><td>Lv4 使用过期食材, Lv7 使用腐烂食材</td></tr><tr><td>农耕 (Farming)</td><td>播种、收获、检查作物</td><td>0/150</td><td>—</td></tr><tr><td>急救 (First Aid)</td><td>包扎、缝合、夹板</td><td>0/75</td><td>Lv2 缝合伤口</td></tr><tr><td>电工 (Electrical)</td><td>拆电器、修发电机、接发电机</td><td>0/75</td><td>Lv3 修发电机, Lv5 拆灯</td></tr><tr><td>金属加工 (Metalworking)</td><td>焊接金属结构、拆金属家具</td><td>0/150</td><td>—</td></tr><tr><td>机械 (Mechanics)</td><td>拆装车零件、修理零件</td><td>0/150</td><td>Lv2 热车, Lv8 修理引擎</td></tr><tr><td>裁缝 (Tailoring)</td><td>修补衣物、给衣服加补丁</td><td>0/150</td><td>Lv8 完全修复衣物破洞</td></tr></tbody></table><h3 id="武器类-combat" tabindex="-1">武器类 (Combat) <a class="header-anchor" href="#武器类-combat" aria-label="Permalink to &quot;武器类 (Combat)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>经验来源</th><th>关键解锁</th></tr></thead><tbody><tr><td>斧头 (Axe)</td><td>用斧类武器命中</td><td>伤害随等级提高</td></tr><tr><td>长棍 (Long Blunt)</td><td>用棒球棍/撬棍命中</td><td>伤害随等级提高</td></tr><tr><td>短棍 (Short Blunt)</td><td>用铁管/锤子命中</td><td>伤害随等级提高</td></tr><tr><td>长刀 (Long Blade)</td><td>使用武士刀</td><td>极其罕见，伤害极高</td></tr><tr><td>短刀 (Short Blade)</td><td>用螺丝刀/猎刀命中</td><td>伤害随等级提高</td></tr><tr><td>长矛 (Spear)</td><td>用矛命中</td><td>伤害随等级提高</td></tr><tr><td>瞄准 (Aiming)</td><td>用枪械命中</td><td>精准度随等级提高</td></tr><tr><td>装弹 (Reloading)</td><td>装填弹匣</td><td>速度随等级提高</td></tr><tr><td>维护 (Maintenance)</td><td>武器使用时耐久不降</td><td>耐久消耗减少</td></tr></tbody></table><h3 id="敏捷类-agility" tabindex="-1">敏捷类 (Agility) <a class="header-anchor" href="#敏捷类-agility" aria-label="Permalink to &quot;敏捷类 (Agility)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>经验来源</th><th>关键解锁</th></tr></thead><tbody><tr><td>冲刺 (Sprinting)</td><td>跑步获得</td><td>速度随等级提高</td></tr><tr><td>轻手轻脚 (Lightfooted)</td><td>潜行移动不触发噪音</td><td>移动噪音减小</td></tr><tr><td>灵活 (Nimble)</td><td>战斗姿态移动</td><td>战斗姿态移动速度提高</td></tr><tr><td>潜行 (Sneaking)</td><td>潜行移动</td><td>被察觉范围减小</td></tr></tbody></table><h3 id="生存类-survival" tabindex="-1">生存类 (Survival) <a class="header-anchor" href="#生存类-survival" aria-label="Permalink to &quot;生存类 (Survival)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>经验来源</th><th>关键解锁</th></tr></thead><tbody><tr><td>钓鱼 (Fishing)</td><td>钓鱼活动</td><td>成功率随等级提高</td></tr><tr><td>诱捕 (Trapping)</td><td>检查/设置陷阱</td><td>成功率随等级提高</td></tr><tr><td>采集 (Foraging)</td><td>搜索模式采集</td><td>Lv5 雷达范围翻倍</td></tr></tbody></table><h3 id="被动类-passive" tabindex="-1">被动类 (Passive) <a class="header-anchor" href="#被动类-passive" aria-label="Permalink to &quot;被动类 (Passive)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>经验来源</th><th>效果</th></tr></thead><tbody><tr><td>体格 (Fitness)</td><td>运动类活动</td><td>耐力恢复速度</td></tr><tr><td>力量 (Strength)</td><td>负重行走、近战</td><td>负重容量和近战伤害</td></tr></tbody></table><h2 id="经验倍率" tabindex="-1">经验倍率 <a class="header-anchor" href="#经验倍率" aria-label="Permalink to &quot;经验倍率&quot;">​</a></h2><ul><li>初始 25% — 职业或特性无加成时的默认经验获取率</li><li>75% — Fast Learner 特性</li><li>100% — 职业直接提供的经验率</li><li>125% — 职业默认 + 职业加成</li><li>各等级经验增量独立叠加</li></ul><div class="tip custom-block"><p class="custom-block-title">练级技巧</p><p>看电视节目 (Life and Living) 是前期最快练级方式。每天 6:00、12:00、18:00 播出。烹饪、木工、采集、钓鱼、诱捕都能通过看电视升级到 Lv3-Lv4。</p></div>',16)])])}const v=d(i,[["render",l]]);export{u as __pageData,v as default};
